/* Every expected record/list byte is generated by executing the original
 * repair routines in both DOS and Windows, not by a second native formula. */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mercsrepair.h"
#include "../tests/fixtures/career-return/repair_original_fixtures.h"

static void expand(mercs_career_mech *m, const repair_patch *p, size_t n)
{
    size_t i;
    memcpy(m->bytes,repair_seed,sizeof m->bytes);
    for (i = 0; i < n; i++) { assert(p[i].offset < sizeof m->bytes); m->bytes[p[i].offset] = p[i].value; }
}

static void equal(const char *name, size_t step, const char *field,
                   const uint8_t *actual, const uint8_t *expected, size_t n)
{
    size_t i;
    for (i = 0; i < n; i++) if (actual[i] != expected[i]) {
        fprintf(stderr,"%s step%zu %s+0x%zx: native%02x original%02x\n",
                name,step,field,i,actual[i],expected[i]);
        abort();
    }
}

static void check(const char *name, size_t step, mercs_repair_session *s,
                   const repair_expect *e, int32_t result)
{
    mercs_career_mech expected;
    size_t i;
    if (result != e->result) {
        fprintf(stderr,"%s step%zu result: native%d original%d\n",name,step,result,e->result);
        abort();
    }
    expand(&expected,e->current,e->nc);
    equal(name,step,"current",mercs_repair_current(s)->bytes,expected.bytes,sizeof expected.bytes);
    expand(&expected,e->reference,e->nr);
    equal(name,step,"reference",mercs_repair_reference(s)->bytes,expected.bytes,sizeof expected.bytes);
    expand(&expected,e->backup,e->nb);
    equal(name,step,"backup",mercs_repair_backup(s)->bytes,expected.bytes,sizeof expected.bytes);
    assert(mercs_repair_funds(s) == e->funds && mercs_repair_dirty(s) == e->dirty);
    for (i = 0; i < 4; i++) {
        size_t n;
        const uint8_t *list = mercs_repair_items(s,(enum mercs_repair_list)i,&n);
        if (n != e->counts[i]) {
            fprintf(stderr,"%s step%zu list%zu count native%zu original%zu\n",name,step,i,n,e->counts[i]);
            abort();
        }
        equal(name,step,"inventory",list,e->lists[i],n * MERCS_REPAIR_ITEM_BYTES);
    }
}

int main(void)
{
    size_t i, j, count = 0;
    for (i = 0; i < REPAIR_FIXTURE_COUNT; i++) {
        const repair_fixture *f = &repair_fixtures[i];
        mercs_career_mech_pair pair, before;
        mercs_repair_session *s = NULL;
        int finished = 0;
        expand(&pair.current,f->current,f->nc); expand(&pair.reference,f->reference,f->nr);
        before = pair;
        assert(f->counts[2] == 0 && f->counts[3] == 0);
        assert(!mercs_repair_begin(&pair,f->lists[0],f->counts[0],f->lists[1],f->counts[1],f->funds,0,&s));
        for (j = 0; j < f->step_count; j++) {
            const repair_step *op = &f->steps[j];
            const int *a = op->args;
            int rc = -999;
            int32_t result = 0;
            if (op->op == 1 || op->op == 2)
                rc = mercs_repair_component(s,a[0],op->op == 1 ? MERCS_REPAIR_ARMOR : MERCS_REPAIR_INTERNAL,0,a[1],&result);
            else if (op->op == 3) rc = mercs_repair_component(s,a[0],MERCS_REPAIR_CRITICAL,a[1],a[2],&result);
            else if (op->op == 4) rc = mercs_repair_all(s,a[0],&result);
            else if (op->op == 5) rc = mercs_repair_owed(s,&result);
            else if (op->op == 6) {
                int leave = -1;
                rc = mercs_repair_finish(s,a[0] != 1,a[1] == 0,&leave);
                result = leave; finished = leave;
            } else if (op->op == 7) rc = mercs_repair_rollback(s);
            else if (op->op == 8)
                rc = mercs_repair_selected(s,a[0],(enum mercs_repair_part)a[1],a[2],&result);
            assert(rc >= 0);
            check(f->name,j,s,&op->expected,result);
            count++;
        }
        /* Read-only caller data must stay untouched, and a finished session
         * cannot debit or reserve another item through repeated delivery. */
        assert(!memcmp(&pair,&before,sizeof pair));
        if (finished) {
            int leave = 77;
            int32_t cost = 88;
            assert(mercs_repair_finish(s,1,1,&leave) == MERCS_REPAIR_INVALID && leave == 77);
            assert(mercs_repair_all(s,0,&cost) == MERCS_REPAIR_INVALID && cost == 88);
            check(f->name,f->step_count-1,s,&f->steps[f->step_count-1].expected,
                  f->steps[f->step_count-1].expected.result);
        }
        mercs_repair_free(s);
    }
    printf("PASS: %zu original repair scenarios, %zu complete native record/list/funds transitions\n",REPAIR_FIXTURE_COUNT,count);
    return 0;
}
